function LoadEpochCNQuestData()
  EpochCN_EpochQuestData = {
    [11]={"悬赏河爪豺狼人","给兵营的瑞尼尔副队长带去8个彩色豺狼人臂章。","豺狼人是一种在这些土地上没有什么体面生意的野蛮生物，人们在艾尔文森林的边界上出现过它们。  一大群它们出没在那边守卫塔以南的树林里，数量远远超出了我们单独处理的能力。  另一群人已经出没于东部石凯恩湖附近的地区。\n\n暴风城军队将表彰任何帮助杀死他们的人。  把他们的彩绘豺狼人臂章带给我作为你行为的证据。","pfQuest-epoch zhCN","Riverpaw Gnoll Bounty"},
    [76]={"玉石矿洞","杀死 10 名狗头人矿工、5 名狗头人风水师，并探索贾斯珀洛德矿井。任务完成后返回金镇去找杜根元帅。","多亏了你，我们才知道法戈迪矿坑里到处都是狗头人。现在我们需要一名侦察员来调查更遥远的贾斯珀洛德矿井。\n\n探索贾斯珀洛德并确认是否有狗头人存在。当你在那里时，如果你看到任何狗头人，就把他们干掉。要到达矿井，请沿着道路向东行驶，直到到达阿佐拉之塔。从塔楼向北走，你会在山麓找到矿井。","pfQuest-epoch zhCN","The Jasperlode Mine"},
    [109]={"向格里安·斯托曼报到","与格里安·斯托曼特尔交谈。他通常可以在西部荒野中部路边哨兵山的石塔中找到。","在我看来，你这段时间见过不少战斗，$c。如果您还没有向 Gryan Stoutmantle 报告，您应该向 Gryan Stoutmantle 报告。他领导人民民兵，旨在保护西部荒野的农田。我打赌他需要你的帮助。你通常可以在哨兵山的石塔里找到他，就在西部荒野中部的路边。","pfQuest-epoch zhCN","Report to Gryan Stoutmantle"},
    [465]={"古杰克的策略","摧毁所有的龙喉投石车。","当你与龙喉战斗时，我们发现了他们的更多计划。\n古杰克已经建造了弹射器，并打算围攻米奈希尔！  随着丹阿尔加兹的战斗，我们实际上被阻止了增援！\n你需要干掉那些弹射器。  他们在龙喉营地。\n给，拿着这个火种。  杀出一条血路，到达弹射器并用火种点燃它们。\n完成这一切后，找到并杀死古杰克。  我们需要砍掉这头龙喉野兽……的脖子。","pfQuest-epoch zhCN","Gujek's Gambit"},
    [474]={"击败古杰克","杀死古杰克将军\n将古杰克的头交给斯托特菲斯特队长。","现在弹弓已经被烧毁，找到并杀死古杰克将军。","pfQuest-epoch zhCN","Defeat Gujek"},
    [487]={"达纳苏斯之路","将 10 个瘤松护身符交给多兰纳尔郊外的哨兵阿马拉·夜行者。","通往达纳苏斯的道路必须保持安全。从多拉纳尔前往达纳苏斯的旅行者们不断报告来自瘤松部落的腐化熊怪的无情袭击。\n\n每天都有重要新闻和商业往来于达纳苏斯。我们不能让一群异教徒流氓恐吓人民。\n\n以神圣森林的名义拿起武器，流氓。他们的巢穴位于这个有利位置下方的某个地方。把他们的神圣护身符带给我并向我报告。","pfQuest-epoch zhCN","The Road to Darnassus"},
    [537]={"黑暗议会","杀死阿古斯暗影法师，并将他们的一本咒语书带回给希尔斯布莱德丘陵南海镇的法官亨利·马雷布。","你带给我的这封信是由一个自称纳迦兹的人写的，他是阿古斯守灵会的成员。我不知道阿古斯觉醒是什么，但如果他们与辛迪加结盟，那么他们一定是一个威胁。 \n\n我希望你找到那封信中提到的阿古斯暗影法师。我要你找到他们，然后杀掉他们。把他们拥有的任何东西都给我，告诉我们这个纳加兹是谁或是什么。\n\n在斯特拉恩布拉德和那里北部的高地搜索。运气好的话，你会在那里找到这些阿古斯守灵使者。","pfQuest-epoch zhCN","Dark Council"},
    [991]={"莱恩的净化","在灰谷找到泰洛尼斯。","$N，我的一个老朋友也在灰谷帮助哨兵，但他还没有回来。\n他找到了一件他认为可以减缓熊怪对我们人民的攻击的物品——一根由现已死去的邪恶巫师制造的权杖。\n在他离开这里之前，他提到要寻找一颗宝石作为权杖。\n他提到这颗宝石可能藏在湖中的神殿里法拉辛位于西边的山脚下。宝石在被淹没之前就被存放在那里。\n请找到我的朋友，$N。","pfQuest-epoch zhCN","Raene's Cleansing"},
    [1132]={"菲欧拉·长耳","和塞拉摩的菲欧拉·长耳谈一谈。","哦，又出海了！  感受风的亲吻，让海浪像我神圣的母亲一样摇晃我，很久以前！\n哦，我希望我有你的财富，好$c，因为我看到了你们未来的大海！\n我的工作就是向渴望的灵魂讲述卡利姆多的土地，机遇之地！  如果您愿意跨海碰碰运气，那么可以从这里乘船前往美丽的塞拉摩港。  在那里与我的伙伴精灵菲奥拉·长耳交谈。\n她将带您踏上卡利姆多冒险之旅！","pfQuest-epoch zhCN","Fiora Longears"},
    [1218]={"沼泽青蛙腿","为尘泥沼泽的“沼泽之眼”加尔收集3棵舒心草。","我喜欢烹饪。  沼泽地烹饪不错。  炸青蛙腿之类的。\n做饭时，我需要香料。  舒缓香料。  那我就做一道炖菜，炖起来，吸下去，​​也给你吃一点。\n你喜欢炖菜吗？","pfQuest-epoch zhCN","Marsh Frog Legs"},
    [1288]={"维米斯的报告*","把维米斯的报告带给吉安娜?普罗德摩尔，她在塞拉摩.","你做了一些很好的工作，$N，是我从业余爱好者那里看到的最好的。\n普罗德摩尔夫人要求我让她了解这一微妙的情况，我已经有一段时间没有和她说话了。\n我本来打算稍后向她提交我的报告，但似乎由你来与她谈论这件事更合适。你可能比我能更好地回答她的问题。","pfQuest-epoch zhCN","Vimes's Report"},
    [2038]={"宾格斯的补给品","查找并返还 Bingles 的用品：\nBingles 扳手、Bingles 螺丝刀、Bingles 锤子和 Bingles 爆弹帽。","好像坠入湖还不够糟糕，来自附近岛屿的穴居人袭击了我，偷走了我的工具和特殊的爆破炮炸药。没有旋翼机，没有炸药，运动就没有机会！\n\n拿回我的工具并找到我的Blastencapper炸药，$N。为了诺莫瑞根！","pfQuest-epoch zhCN","Bingles' Missing Supplies"},
    [3382]={"危难中的船长","帮助瓦妮莎·贝蒂斯船长、她的船员和地平线轻帆号上的乘客抵御纳迦的攻击。瓦妮莎·贝蒂斯船长必须存活。","我们刚刚在海岸附近寻找一个安全的避风港抛锚。他们攻击时太阳还没有落下一个多小时……那些该死的纳迦！\n我不确定他们在寻找什么，但很明显他们没有找到——他们已经回来过一次了。我的几个侦察兵正在山谷入口处警戒，以便在下一次袭击到来时向我们发出合理的警告。\n很抱歉你现在才来，$n，但这不属于我的控制范围。\n你准备好迎接你一生的战斗了吗？","pfQuest-epoch zhCN","A Crew Under Fire"},
    [8905]={"热心的建议","将15份冬泉谷血样、20枚金币以及一副野性之心护腕交给铁炉堡的德莉亚娜。","很高兴见到，$c。  我有一些你可能感兴趣的东西。\n\n我拥有一套盔甲，很像你们职业的人所穿的盔甲，但质量要高得多。  我愿意用护腕换取普通护腕，以换取一点小恩情。\n\n居住在冬泉谷的霜豹和熊的血液拥有我目前所需要的特性。  给我带来相当大的样品以及护腕和少量黄金。  你会发现你的努力是值得的。","pfQuest-epoch zhCN","An Earnest Proposition"},
