    [26262]={"安西昂的临别赠言","将一对勇气腿铠带给铁炉堡的黛莉安娜。","Valthalak 的灵魂被储存在这个护身符中。  由于贪婪，我们愚蠢地将它分成了三部分，不知道等待着我们的诅咒。\n\n阻止瓦尔塔拉克咒语的唯一方法就是将奖章重新组合在一起。  返回黛莉安娜身边并告诉她博德利是她找到剩余碎片的唯一希望。  和她谈谈你安排的任何奖励。\n\n我，这一次，应该安息了。  祝你好运；你会需要它的每一点！","pfQuest-epoch zhCN","Anthion's Parting Words"},
    [26263]={"安西昂的临别赠言","将一对勇气腿铠带给奥格瑞玛的莫克瓦尔。","瓦尔塔拉克的灵魂被储存在这个护身符中。  由于贪婪，我们愚蠢地将它分成了三部分，不知道等待着我们的诅咒。\n\n阻止瓦尔塔拉克咒语的唯一方法就是将护身符重新组合在一起。  返回莫克瓦并告诉他博德利是他找到剩余碎片的唯一希望。  和他谈谈你安排的任何奖励。\n\n我，这一次，应该安息了。  祝你好运；你会需要它的每一点！","pfQuest-epoch zhCN","Anthion's Parting Words"},
    [26264]={"合同#1010：魔法残留","从巴拉丁要塞收集 4 瓶魔法残留。","我为愿意组建团队的承包商提供了工作机会。是时候发挥假期的魔力了！这是节日装饰部门的一份。\n\n合同 #1010：从巴拉丁要塞内获取魔法残留物\n\n数量：四个样品","pfQuest-epoch zhCN","Contract #1010: Magical Residue"},
    [26265]={"奥术茶点","向巴拉丁堡的某人学习如何召唤水晶水，然后将 20 个召唤出来的水晶水交给位于英勇之眠的纳拉斯·月枝希利苏斯。","万岁$C！我需要你的帮助。\n\n沙漠的干热让人和动物都感到焦渴。我听说托尔巴拉德的肯瑞托可能有一种特殊的方法可以召唤出最清爽的水晶水。您是否愿意前往那里看看您是否可以了解这是如何完成的，以便您可以补充我们的物资？","pfQuest-epoch zhCN","Arcane Refreshment"},
    [26266]={"黑暗文学","从诅咒之地的荒原中的邪教成员那里收集 8 本影誓书籍。","你是部落的一员，对吧？我正在寻求加入一个派系，考虑到所有因素，我认为这是显而易见的选择...\n\n莫格里亚和她的商队在我的营地遇到了我。当我们各自解释为什么我们在这里时，嗯……这是一场在扭曲的虚空中进行的比赛——你相信我们的目标完全一致吗？所以，我们暂时同意：我提供关于魔石要塞的情报以及解决这个诅咒的方法，以换取部落公民身份。\n\n关于诅咒，我有一个可能会成功也可能不会成功的计划。这不是永久的解决方案，但我可以尝试给部落一点喘息的机会。也就是说——只要我能得到只有“PH0”才能提供的帮助。“NL”“NL”我需要附近的邪教徒的书籍，特别是那些练习魔法或仪式的人。暴徒和执法者不会这么做。书本越厚越好。当我拥有它们时，我会解释更多。","pfQuest-epoch zhCN","Dark Literature"},
    [26267]={"逆转痛苦","从魔石堡垒内的术士那里获得痛苦雕文。","<伊扎尔尼尔弯下腰，用乳白色的眼睛长时间浏览魔法书的页面。最终，他抬头看着你。>\n\n你遇到过类似这样的东西吗？写在卷轴上的东西，或者甚至是石头上的东西？\n\n<伊扎尼尔向你展示了一页充满混乱的文字，周围环绕着一个看起来邪恶的符文。>\n\n术士们正在用这些来玩弄诅咒——篝火——以我认为不可能的方式。哈，傻瓜们甚至用它来炼金术。\n\n如果我们要继续，我需要这些雕文之一，而且我不认为除了费尔斯通的术士之外还有人会拥有这样的东西。一个人去要塞太危险了，所以带上朋友吧。我会继续读下去，直到你回来。","pfQuest-epoch zhCN","Reverse Affliction"},
    [26268]={"改写诅咒","从魔石要塞周围收集 5 个库日尔阿特拉门图瓶。","看到这里雕文的铭文了吗？它的墨水是库日尔阿特拉门图姆（kuzhir atramentum）：非常有效，而且很难获得，即使对于术士也是如此。墨水的主要成分是恶魔之血，呈现出吞噬光芒的黑色光泽。\n\n嗯……他们使用的词汇来自国外的阿古斯唤醒圈。我可以阅读足够多的内容来进行自己的调整，但我没有自己的笔记。\n\n<伊扎尔尼尔带着期待的笑容看着你。>\n\n请给你一些好吗？术士和他们的追随者拥有它们。我敢打赌你会在堡垒周围的术士帐篷里找到它。小屋可能也有一些。","pfQuest-epoch zhCN","Rewriting Curses"},
    [26269]={"灵魂燃料","从邪石要塞内的邪教徒尸体中为伊扎尼尔找到 1 块格罗博拉灵魂石。","当你拿着这个字形时，你有什么感觉？恶心？一种抓不住的痒？\n\n<伊扎尼尔将手放在符文上，闭上眼睛。>\n\n对我来说，这是我头上的重击。就像……有人把笼子弄得嘎嘎作响。我听说有强大的灵魂石从费尔斯通后面的某个洞穴里走私出来……假设我们这里的雕文就是这样充电的，这可不是什么小事。\n\n那个洞里的兽人处于另一个层面，不会屈尊与任何人交往。也就是说，有时盗窃、交易或一个简单的错误会导致他们梦寐以求的一颗宝石落入不该出现的地方。\n\n也许您已经见过一些了？我至少需要一个才能让我的计划取得成果。费尔斯通周围的术士可能有一些。\n\n如果你觉得自己很鲁莽，你也可以尝试一下洞穴本身。它位于费尔斯通中心的西边，入口处环绕着巨大的骨头。我从未进去过，但我听过故事...","pfQuest-epoch zhCN","Soul Fuel"},
    [26270]={"遥远的干扰","在费尔斯通最南端露台上的高坛祭坛上使用痛苦改变雕文。","到了我们最后一幕的时候了。你们的队伍现在已经熟悉了费尔斯通的危险，所以希望这不会太困难。\n\n计划是这样的：将修改后的雕文带到费尔斯通南部最高平台上的祭坛上，并在仪式圈上使用它。这是一个散发着黑暗魔法的紫色符文。从理论上讲，这个雕文会将诅咒从目标上撕开，并将其返回仪式圈——正如我所说，这不是永久的解决方案。\n\n我不知道这样做的后果，所以要做好一切准备。祝你好运，$N。","pfQuest-epoch zhCN","Distant Disruption"},
    [26271]={"远古宝石切割","星落村的埃莉诺·月光希望你从冬泉谷较大的上层精灵废墟中找回一套上层精灵工匠工具包。","您好，希望您喜欢冬泉谷！我喜欢来自黑海岸的阴暗的干燥空气。你是个冒险家，对吧？\n\n我是一名学生珠宝商，来这里是为了寻找周围地区那些漂亮的水晶。有传言说它们是从天上掉下来的——这可能就是这个村庄得名的原因！不过，我随身携带的工具并不能塑造它们。相信我，我试过了！我最好的研磨机坏了……！\n\n这些水晶不是什么新东西，所以古代上层精灵肯定有某种方法来切割它们，对吧？你能找到的任何东西我都会付钱！凯瑟瑞尔在南方，而……特莱斯阿兰在东北方，但通往那里的路上有一位卑鄙的老太太。","pfQuest-epoch zhCN","Ancient Gemcutting"},
    [26272]={"我们需要维修！","将上层精灵工匠套件交给永望镇的费尔诺克·钢泉。","嗯...这个套件真的很旧...我现在用起来还不太舒服。\n\n<埃莉诺抓着眉头，以令人惊讶的敏锐眼睛检查工匠套件。>\n\n哦，我知道！我在永望镇遇到了一个妖精，并借给了他一些物资。他是一名工程师，欠我一个人情！你正往那个方向走吗？你介意把这个交给他吗？只要告诉他是我派你来的，我将很感激能恢复它。","pfQuest-epoch zhCN","We Need Repairs!"},
    [26273]={"流星","星坠村的埃莉诺·月光希望你从冬泉谷周围收集 10 颗星坠水晶。","这太令人兴奋了，$N！我迫不及待地想开始制作珠宝。我确信费尔诺克是一位优秀的工程师，但对于任何修复这么古老的文物的人来说都是一个挑战。\n\n与此同时，我们为什么不收集尽可能多的水晶呢？一切尘埃落定后，我会给你做一件珠宝！这听起来公平吗？","pfQuest-epoch zhCN","Falling Stars"},
    [26274]={"费尔诺克的技巧","从永望镇的费尔诺克钢泉处领取修复后的工匠工具包，然后返回冬泉谷星落村的埃莉诺·月光。","好吧，$N。我本来想和你一起去拿工具包，但把这些珠宝独自留下我觉得不舒服……如果有人偷了它们怎么办？\n\n很抱歉这么依赖你。我会补偿你的，我保证！不，我不懒！","pfQuest-epoch zhCN","Felnok's Finesse"},
    [26275]={"送给您的礼物！","从埃莉诺身后房子内的板条箱中取出宝石镶嵌袋。","<埃莉诺小心翼翼地尝试塑造其中一颗晶体。>\n\n嗯...也许我会让费尔诺克来解释一下这些额外的东西是做什么用的。值得庆幸的是，这些工具运行良好，所以我现在就塑造您的宝石！\n\n应该不会花很长时间！我身后房子里的板条箱里有一袋设置。你能做最后一件事，把包拿给我吗？请？！","pfQuest-epoch zhCN","A Gift, For You!"},
    [26276]={"行动：方阵","从黑石深渊的方阵中为暴风城的沉默者肖尼取回黑曜石核心。","我们仍在研究一种有效的方法来钻探诺莫瑞根并开始修复对城市的破坏。我们需要的是更多的力量！ \n\n我有一个表弟在黑石深渊的某个实验室找到了一份工作。他们在那里建造由黑曜石核心提供动力的傀儡。我想检查其中一个核心，看看它是否适合我。 \n\n我的表弟提到有一个名为 Phalanx 的老傀儡，它使用黑曜石核心。它即将退役——所以如果你能获得它的核心，任何人都不应该错过它！","pfQuest-epoch zhCN","Operation: Phalanx"},
    [26277]={"烈焰萨满","杀死黑石深渊的烈焰法师罗雷格兰，然后返回安戈洛环形山元帅避难所的亚鲁尼火焰观察者。","我在大地之环的职责包括监控萨满对火能的使用和滥用。最近我感觉到一股强烈的火势从远处——黑石山传来。 \n\n我相信大地之环的一位前成员已经开始与居住在山脉深处的黑铁矮人接触，并正在尝试混合萨满使用的火元素能量和法师使用的奥术火魔法。 \n\n这种对要素的歪曲必须停止。我需要在这里继续我对原始魔法的研究——但也许你和几个同志可以对付这个流氓萨满。 \n\n他的名字是Tonaka Loregrain。","pfQuest-epoch zhCN","Shaman of the Flame"},
    [26278]={"炎魔之王的副官","杀死黑石深渊的罗科勋爵和弗雷莱什大使，然后返回艾萨拉的海达克西斯公爵。","你已经向我展示了你可以击败我们的敌人并执行任务以推进水王的事业。但到目前为止，你只面对过较小的敌人……现在是你承担更高技能和危险的任务的时候了。 \n\n在黑石山深处，黑铁矮人与火焰领主的仆人密谋。杀死他的两名首席使者：罗科尔勋爵和弗莱拉什大使。 \n\n这样做可以向我证明您对我们事业的奉献精神。","pfQuest-epoch zhCN","The Firelord's Lieutenants"},
    [26279]={"更好的东西","杀死黑石深渊深处的玛格姆斯，然后返回燃烧平原摩根守夜场的奥拉留斯。","Winky船长是一个痛苦的失败者。我说太难了！ \n\nWinky 说黑铁矮人有好东西，但我说不！一定有更好的东西。 \n\n我听说有。 \n\n它的名字叫Mag。妈。 \n\nMag。妈。 \n\nMag。穆斯。马格穆斯！杀了它！也许不是用火。","pfQuest-epoch zhCN","The Gooder Stuff"},
    [26280]={"任性的学生","杀死暴风城的猎犬大师格雷布玛并为乌菲尔·铁须取回他的猎人学校文凭。","好吧，我从来没有！ $N，很抱歉，我需要叶这样的冒险家的帮助。 \n\n我刚刚得知我以前的一名学生被发现在黑石深渊训练恶魔犬。他应该杀死恶魔，而不是与他们交往！ \n\n我想撤销授予他的文凭——他的名字是格雷布玛——但黑铁城不欢迎我们铁炉堡矮人。你能传达坏消息并取回毕业证书吗？","pfQuest-epoch zhCN","The Wayward Student"},
    [26281]={"永恒之火","将永恒余烬带给暴风城的黑暗束缚者加金。","检查余烬后，您会发现它感觉还活着，在您手中脉动。你记得听说黑暗束缚者加金有处理此类奇怪物体的经验，也许能够进一步调查。\n\n你可以在暴风城法师区的被宰杀的羔羊中找到他。","pfQuest-epoch zhCN","An Eternal Flame"},
    [26282]={"一笔旧债","在 Glittermurk 矿井中找到主管 Grimgash 并杀死他。","你看起来是那种有进取心的人，愿意接受一份工作而不用问太多问题。正是我一直在寻找的类型。\n\n在我在 Springsocket 定居之前，我曾经有自己的生意，将货物从一个地方运送到另一个地方。那时我有一个“合作伙伴”，他帮助……消除了海关和文书工作中的粗糙边缘。然后风险投资公司介入并从我手下招募了他们，整个运作就崩溃了。我被困在沙漠里了！\n\n即使事情顺利，哥布林也不会忘记那种恩怨。我得留在这里照管我的事业，但如果你愿意拜访闪光莫克矿山的主管格里姆加什，我会很乐意奖励你。","pfQuest-epoch zhCN","An Old Debt"},
    [26283]={"阿佐坦遗物","在铁炉堡找到一位知识渊博的历史学家。","在你面前的是一个古老而饱经风霜的偶像，隐约呈现出一个深不可测的远古人类的形状。知识渊博的历史学家可能会对此感兴趣——其中最著名的可以在铁炉堡探险家大厅中找到。","pfQuest-epoch zhCN","Azothan Relic"},
    [26284]={"Azothan 遗物","在 Glittermurk 矿井中收集 Azothan 遗物。","据说数千年前，巨魔与一个被称为阿佐萨的群体发生了战争。人们对它们知之甚少，但是我们的一些更古怪的策展人，包括我自己，相信这里的东西比我们看到的要多得多。\n\n如果你所说的是真的，并且风险投资公司偶然发现了他们的文物，那么你必须把它们带给我。它们属于博物馆！你愿意深入研究他们的矿井并为我收集尽可能多的东西吗？","pfQuest-epoch zhCN","Azothan Relics"},
    [26285]={"迪格失落的烟斗","从闪光暗矿矿中的暗黑处找回迪格丢失的管子，并将其带到藏宝海湾交给他。","没有一些恶习的生活是什么样的，呃$C？\n\n可悲的是，自从我在镇东边的海滩上把我最喜欢的烟斗弄丢后，我就再也不能抽它了。我有点不知所措，如果你明白我的意思的话，当我清醒过来时，我看到一个大鱼人带着它逃跑了！\n\n看来鱼人在闪光矿坑里安了家。如果你碰巧碰巧有机会拿走我的烟斗，我将非常感激。","pfQuest-epoch zhCN","Deeg's Lost Pipe"},
    [26286]={"杀死工头","杀死 Glittermurk 矿山内的风险投资公司工头。","风险投资公司在那儿有一整套该死的采矿场！难怪我要费尽心思才能得到任何歌唱水晶。如此规模的行动很可能会导致丛林的根基崩溃。在事情失控之前，必须得有人来处理它！\n\n帮我一个忙，去消灭竞争对手，把闪闪发光矿井工头的头给我带来。他走了之后，我不仅可以开始在这里赚取一些可观的利润，而且丛林也不会在此过程中被破坏！","pfQuest-epoch zhCN","Kill the Foreman"},
    [26287]={"棱柱鳞片","从闪光矿井内的蛇怪身上收集棱柱鳞片，并将其带到藏宝海湾的崔兹利克。","由于您在完成我的 Excelsior 系列靴子订单方面提供了很大的帮助，我认为您应该帮助我进行实验性的新设计。\n\n我正在从鳄鱼皮扩展到蛇怪 - 但不仅仅是任何蛇怪。我只想要最好的。我听说风险投资公司在 Glittermurk 矿区发现了一只巨大、闪亮、特殊的蛇怪。这就是我需要的。出去把它的鳞片带给我！","pfQuest-epoch zhCN","Prismatic Scales"},
    [26288]={"回收工具","从 Glittermurk 矿山内的风险投资公司回收 20 个工具。","所以这是一笔交易“PH0”——几个月前，我被委托为荆棘谷内正在进行的某项行动制作一些高质量的工具。工头称它为“闪光”……什么的。闪闪发光！\n\n我不知道他们在挖什么，但他们在矿井上投入了人力，并为矿工提供了工具，并投入了黄金。\n\n从那时起，我在塔纳利斯收到了更有利可图的佣金，我需要我能拿回来的所有工具来完成订单。\n\n如果你把这件事保密，我想你可以走了并“恢复”我从 Glittermurk 矿工那里制作的工具，每个人都很高兴。好吧，减去 Glittermurk 笨蛋，哈哈。说什么？","pfQuest-epoch zhCN","Reclaiming Tools"},
    [26289]={"叛徒纳迦","在闪光矿井中杀死 5 名潮水神谕者、5 名潮水战士和咬伤者。","作为女王的长期仆人，我痛恨不忠。然而，误入歧途的纳迦在腐败的深渊仆人的带领下迷失了方向。\n\n你喜欢小差事，不是吗，凡人？怎么样：漂洋过海去妖精挖掘的地方。这是一个深入内陆的地方，那里太干燥，无法冒险。地精们误入了一个任性的纳迦巢穴，这些纳迦的领导者是被他们称为“格纳什”的人。杀死格纳什的仆人，然后结束他的存在。\n\n因为我们不能让任何反抗女王的人活下去。","pfQuest-epoch zhCN","Renegade Naga"},
    [26290]={"巨魔遗物","在奥格瑞玛找到一位知识渊博的博学者。","在你面前的是一个古老而饱经风霜的偶像，其形状隐约是一个深不可测的远古人类。这可能会引起知识渊博的巨魔传说者的兴趣——其中最著名的是奥格瑞玛精神谷。","pfQuest-epoch zhCN","Troll Relic"},
    [26291]={"巨魔遗物","在闪光矿井中收集巨魔遗物。","传说中，数千年前，巨魔与一个只被称为德阿佐萨的群体交战。除了他们在战斗中的坚韧之外，人们对他们知之甚少。我相信这里的东西比你所看到的要多得多。\n\n如果你说的是真的，并且 de Venture Co. 偶然发现了他们的文物，那么你必须把它们带给我。你愿意深入研究他们的矿井并为我收集尽可能多的东西吗？","pfQuest-epoch zhCN","Troll Relics"},
    [26292]={"隧道怪物","在闪光矿井中寻找艾利斯·潮汐所描述的怪物并摧毁它。","我知道这对于精灵来说很不寻常，但我喜欢大海。我在藏宝海湾以东的浅滩上漂浮了好几个小时，与鱼和鸟交朋友。我从来没有感到害怕......直到最近。\n\n我正比平常更向北漂浮父亲，这时一些巨大的神秘卷须从海底伸出并抓住了我的腿！这个生物试图把我拉进水下隧道，但我反击了。最后，它释放了我，消失在隧道里……隧道在它后面塌陷了。\n\n我想这个生物可能就生活在风险投资公司在城镇北部山上建立的那个挖掘坑里。我试图警告他们，但他们不理睬我。如果你进入那些矿井，请小心怪物！我担心其他人会在不知不觉中遇到它。","pfQuest-epoch zhCN","Tunnel Monster"},
    [26293]={"适合国王","从菲拉斯各地的流浪森林行者那里收集行者树枝。","你看上去不太忙……来点小任务怎么样？我被热砂贩毒集团派到这里来对冲一个小赌注。格鲁克认为有一天他会成为戈多克国王，就像他的父亲在他之前一样，但现任国王把他标记为叛徒，并将他驱逐出厄运之槌。我们认为格鲁克具备成为国王的条件……在朋友的帮助下。\n\n我计划为格鲁克打造一件强大的武器，他可以在即将到来的战斗中使用，而你将为我提供我需要的所有零件。交易？\n\n我首先需要的是一种特殊类型的魔法木材，你可以在附近的森林行者那里找到。它很轻，但与任何金属一样坚固，可以制作精美的手柄。","pfQuest-epoch zhCN","Fit For A King"},
    [26294]={"适合国王","在格鲁克大院为维果收集 8 蒲式耳湿地大麻。","在这些部分周围生长着一种特殊类型的大麻，我可以用它来制作一根非常坚固的绳子。这将确保即使国王失去控制，他也不会失去武器！\n\n食人魔很奇怪。有传言说，格鲁克的父亲，前任国王，吸了一蒲式耳这种东西后就离开了王位。等他离开食人魔的视线后，他们就宣布了新国王，从而结束了格鲁克对王位的要求。\n\n无论如何，大麻生长在菲拉斯靠近河流的地方，在森林里随处可见。","pfQuest-epoch zhCN","Fit For A King"},
    [26295]={"适合国王","从菲拉斯的虚弱野兽身上收集 20 瓶野兽之血。","我的计划的一个重要部分需要高度精炼的铁，其中散布着一种特殊的合金，你稍后会为我收集。然而，这些地方的铁很难获得！\n\n不过我有一个解决办法：我不需要太多，所以我们可以从菲拉斯这里的野兽身上提取铁。\n\n这是一个我称之为 Hemovac Max 的小玩意。削弱一头野兽并直接吸走它们血液中的铁！有了足够的小瓶，我就有足够的铁来使用。可悲的是，由于每瓶的数量如此之少，所以是时候进行一场老式的野生动物屠杀了。","pfQuest-epoch zhCN","Fit For A King"},
    [26296]={"适合国王","从菲拉斯的扭动深渊收集 12 块异种蝎合金。","现在来谈谈……不太令人愉快的事情。我等到你感到投入之后才向你提出这个问题，这是有原因的。在这里的东南方你会发现扭动深渊。这里是被一些人称为异种蝎的掠食野兽的家园。\n\n众所周知，有时它们会误将矿石当成食物，并在上面涂上一层粘稠的软泥。你知道当它们完全消耗并……通过……时会发生什么吗？\n\n好吧，我们得到的是不匹配的矿石，以某种方式形成了新的合金。别问我怎么做；我从来不想检查一个人的内部来找出答案。我只关心你给我那些格鲁克新武器的合金。","pfQuest-epoch zhCN","Fit For A King"},
    [26297]={"适合国王","从灼热峡谷内的土元素和火元素收集旋转熔岩和炽热火焰精华。","我们离最终制造出这把王者武器已经不远了。现在的瓶颈很简单：产生和维持热量。这里的熔炉非常适合生产食人魔通常喜欢使用的标准低质量食物，但它的温度不足以熔炼这些合金并将它们与铁结合起来。\n\n不幸的是，这意味着热量必须传到我们这里。在遥远的东方，在东部王国，你会发现灼热峡谷。\n\n这是一个熔岩流动、岩石融化、元素狂野的地方。我需要你收集他们的炽热精华并把它们带给我。\n\n有了这些精华，我可以加强这个熔炉来满足我们的需求。","pfQuest-epoch zhCN","Fit For A King"},
    [26298]={"适合国王","从菲拉斯海岸的水元素那里收集咸味冷却精华。","热量只是这个方程$c 的一半。我们需要能够调节火焰并控制热量，慢慢地让合金熔化、融合并成为全新的东西。你很幸运，我不必派你到很远的地方来获取我们需要的东西。\n\n就在菲拉斯海岸上，你会发现水元素，它们一直在吸收海洋本身的冷却精华。去尽可能多地收集它，我们将在锻造过程中使用它，以避免烧毁整个建筑！","pfQuest-epoch zhCN","Fit For A King"},
    [26299]={"适合国王","进入玛拉顿并杀死诺克西恩。收集他的精华并带给菲拉斯的维戈。","好吧，别再想你今天过得轻松了。我听说只有一个地方可能有我们需要的东西：被称为玛拉顿的半人马出生地。\n\n在橙色洞穴深处，你会发现一种极其强大的水元素，称为“诺克西恩”，它的精华将成为比这更强大的武器更有价值的试剂。\n\n你愿意冒着生命危险为我获取他的精华吗？我保证，一旦格鲁克统治厄运之槌，这一切都会得到回报！","pfQuest-epoch zhCN","Fit For A King"},
    [26300]={"适合国王","让迪伊和杜姆冷静下来，同时锻造格鲁克的新武器。","我身后的这两个笨手笨脚的人是迪伊和杜姆。他们远谈不上聪明，但他们很擅长用大锤子敲击铁砧，所以就我而言，他们和普通铁匠一样聪明。\n\n当他们锻造武器并在高温下受苦时，我需要你平息火焰并用来自诺克西恩的精华冷却它们。不要让食人魔过热，否则这一切都将化为乌有。","pfQuest-epoch zhCN","Fit For A King"},
    [26301]={"适合国王","交付格鲁克的新武器。","是时候向格鲁克展示这件冠军武器了。你愿意为我做这个荣幸吗？\n\n他在附近的山洞里。","pfQuest-epoch zhCN","Fit For A King"},
    [26302]={"腐败之源","为 Squigglecord Outpost 的 Selrai Dewlight 收集玛拉顿内塞莱德拉斯公主的样本。","口述历史称，这些土地曾经郁郁葱葱，但瑟莱德丝公主在玛拉顿释放半人马引发了一场灾难，创造了我们周围所见的土地。我的目标是在迪比和凯利的帮助下恢复这些土地。\n\n我们需要进一步调查的一个关键部分是公主本人的样本。杀死她不仅会终结进一步的腐败，而且通过仔细研究她，我们也许能够扭转局面。\n\n请代表我深入研究玛拉顿并为我取回样本。我会给你丰厚的报酬。","pfQuest-epoch zhCN","The Source Of Corruption"},
    [26303]={"协调核心","在艾萨拉海岸附近的一座岛屿上寻找海达克西斯公爵。","哦，看，这是$N。我以前见过你从我身边经过，没有注意到这个地方的独特性。距离我站立的地方不到两步，有一条稳定的撕裂现实，通向黑石山的中心深处，到达一个被称为熔火之心的地方。对于像你这样的冒险家来说，这里充满了巨大的邪恶，但也带来了巨大的荣耀。你想看看吗？ \n\n当然愿意，但是对于像你这样的凡人来说，在没有帮助的情况下冒险去那里太危险了。幸运的是，我来这里是为了推动你走向正确的方向。 \n\n寻找居住在艾萨拉海岸的海达西亚水王。他们对您的成功有既得利益。","pfQuest-epoch zhCN","Attunement to the Core"},
    [26304]={"协调核心","将 5 个火焰花、5 个寒冬、一个元素之火和一个元素水带给艾萨拉海岸附近岛屿上的海达克西斯公爵。","熔火之心是我们的死敌——火元素的巢穴。如果不加以控制，他们的力量将会不断增强，直到点燃整个艾泽拉斯。 \n\n即使对于炎魔之王的黑铁盟友来说，狂暴的山中心也太热了。但是，如果你执行我的命令，我将赐予你一个恩赐，让你能够承受火山中心的酷热。 \n\n首先我需要在仪式中消耗元素材料。收集元素火、元素水、一些火焰花和一些凛冬之咬。如果你自己在世界上找不到这些东西，我相信凡人会在某种贸易中心出售它们。","pfQuest-epoch zhCN","Attunement to the Core"},
    [26305]={"协调核心","将托里德的炽热核心和基尼斯的冰冻核心带给艾萨拉海岸附近岛屿上的海达克西斯公爵。","接下来我们需要注入与火和冰结合的强大存在的精华。 \n\n在燃烧平原的风暴祭坛附近，您会在熔岩瀑布中找到托里德。杀死他并取回他的火焰核心对世界来说是一个福音。 \n\n至于霜冻，你需要在冬泉谷杀死我的表弟基尼斯。他居住在凯尔瑟利尔湖以南的冰冻瀑布沿岸。 \n\n这是一个不幸但必要的牺牲。","pfQuest-epoch zhCN","Attunement to the Core"},
    [26306]={"协调核心","用黑石深渊熔火之心入口附近流动的熔岩填充隔热瓶，并从附近的墙上收集核心碎片。","现在您必须收集试剂以适应山上的热量。我们需要来自熔火之心本身的热量和共振样本——或者尽可能接近的样本。 \n\n进入黑铁矮人的据点黑石深渊。走到最底层，你就会找到他们的冶炼站。用附近沸腾的熔岩填充这个隔热瓶。 \n\n然后穿过桥前往核心并从附近的墙上收集碎片。 \n\n毫无疑问，凡人，这是一项危险的任务，你不会想独自完成的。如果你还活着的话，之后就回到我身边。","pfQuest-epoch zhCN","Attunement to the Core"},
    [26307]={"协调核心","保持不动，海达克西斯公爵会为你赋予保护咒，让你安全地进入熔火之心。","我将使用你们收集到的组件来赋予你们我的祝福。它只会在熔火之心保护你，因为它适应了山脉的独特共鸣。 \n\n凡人坚持住！这可能会有点烧伤，但如果你想在黑石山的中心生存下来，这是一个必要的罪恶。","pfQuest-epoch zhCN","Attunement to the Core"},
    [26308]={"意志试炼","与幽暗城的堕落骑士交谈。","很高兴见到，$C $N。我最近去了幽暗城，有机会和堕落骑士交谈。\n\n<圣骑士咯咯地笑。>\n\n有一天我想知道她的真名，这样称呼她感觉很不专业。不过，她还是很看重你的潜力，想让我把你送到她那里去接受一些考验。前往幽暗城冒险并寻找她。","pfQuest-epoch zhCN","Trial of the Willing"},
    [26309]={"意志试炼","如果您想接受考验，请与幽暗城的堕落骑士交谈。","我不再是以前的我了，$C $N。白银之手的骑士，一位德高望重的圣骑士。真理和正义的捍卫者。现在我躺在幽暗城的深处，在这片粘液中寻找病态的生物。\n\n然而，你却表现出了与黑暗作斗争的意愿，尽管所说的黑暗存在于你自己的灵魂中。我想审判你，如果你接受的话。","pfQuest-epoch zhCN","Trial of the Willing"},
    [26310]={"意志试炼","击败位于血色修道院东边墓地的三个前圣骑士的鬼魂。当你安息了灵魂后，回到幽暗城的堕落骑士那里。","在你的第一次试炼中，你需要前往提瑞斯法林地的东北部很远的地方。它位于血色修道院的东边，但要小心不要离修道院太近，因为你的实力还不够强大，无法到达那里。你应该找到一条通往墓地的小石路。\n\n在那个墓地你会发现三个圣骑士鬼魂。生前他们作为一个团队一起工作，死后他们埋葬在自己的安息之地。我感觉他们仍然依附于这个世界。去释放他们吧，让他们终于可以休息了。","pfQuest-epoch zhCN","Trial of the Willing"},
    [26311]={"圣光材料","将信件和付款交给奥格瑞玛荣誉谷的铁砧阿图尔克。","现在是时候打造一把配得上圣骑士的锤子了。我在奥格瑞玛认识一位优秀的铁匠：他的名字叫铁砧阿图尔克。将这封规格和付款信函交给他，他将为您提供一份您需要为他收集的材料清单。你会在荣誉谷的锻造训练师那里找到他。\n\n在我一生中，我会向铁炉堡请求一件工艺品，但我有一种感觉，现在他们可能不会接受这个请求。","pfQuest-epoch zhCN","Materials of the Light"},
    [26312]={"圣光材料","使用阿图尔克的材料清单，找到一些祝福锭、泽勒玛之锤、银手奖章和科尔宝石。把它们带到奥格瑞玛的铁砧阿图克那里。","我花时间磨练自己的技能并学习可以使用的材料。在我的旅行中，我发现了一些对你的狼牙棒有用的资源。 \n\n<Aturk 冲向 Ox，让他写下自己的要求。>\n\n拿着这封信，去取！","pfQuest-epoch zhCN","Materials of the Light"},
    [26313]={"光明武器","","阿图尔克对自己印象深刻，这是一把不错的武器。适合部落的强大成员！好好为我们服务吧，$N，因为你很有才华。\n\n我不后悔怀疑过你，这样的怀疑给了你证明自己的动力！又名玛戈什！","pfQuest-epoch zhCN","Weapon of the Light"},
    [26314]={"茶点仪式","在通灵学院杀死詹迪斯·巴罗夫，并取回高阶魔法师安德洛玛斯的奥术茶点笔记。","冰雹$N。我可以请你帮个忙吗？\n\n早在第三次战争之前，我就与詹迪斯·巴罗夫（Jandice Barov）有着密切的私人关系，她是一位才华横溢的魔术师。当天灾军团袭击洛丹伦时，我的一些个人物品被留在了詹迪斯手中。考虑到我们分手时的情况，我不想再面对她的愤怒。\n\n但是你对奥术的掌握可以与我相媲美，我相信你可以与她正面交锋。如果你愿意从她那里取回我的奥术茶点笔记，我很乐意与你分享笔记的内容。我想你会发现茶点仪式非常节省时间！\n\n你和你的同伴可以在西瘟疫之地通灵学院的地下室找到贾妮丝·巴罗夫。","pfQuest-epoch zhCN","Ritual of Refreshment"},
    [26315]={"茶点仪式","与暴风城法师区的高阶魔法师安德洛玛斯交谈","您好，$N。你在训练中已经变得强大了，我相信我已经没有什么可以教你的了。我打赌你已经厌倦了为你的盟友召唤食物和饮料了，是吗？如果我是对的，我想你应该和暴风城的高阶魔法师安德罗梅斯谈谈。我相信他知道更好的方法。","pfQuest-epoch zhCN","Ritual of Refreshment"},
    [26316]={"洛德伦的法律遗产","在幽暗城为博学者埃伯洛克在通灵学院和斯坦索姆找到有关洛丹伦法律实践的书籍。","生前我是一名法律学者，死后我想继续这些研究，即使我探索更广泛的主题。我没有时间出去从洛丹伦废墟中寻找书籍，但我打赌你会的。\n\n从斯坦索姆废墟和通灵学院给我带来这些特定的书籍，我将能够平衡我的Lorespeaker职责和我的个人兴趣。","pfQuest-epoch zhCN","Lorderon's Legal Legacy"},
    [26317]={"阿塔莱石板","从阿塔哈卡神庙收集阿拉尼石板和贾卡里石板。","居住在悲伤沼泽的阿塔哈卡沉没神庙内的阿塔莱巨魔据说持有两块我想研究的古代石碑。\n\n考虑到他们会在我开口询问之前杀掉我，我需要一种冒险精神去下去取回它们。对工作感兴趣吗？","pfQuest-epoch zhCN","Atal'ai Tablets"},
    [26318]={"血神的召唤","从阿塔哈卡神庙的阿塔莱巫医和阿塔莱高祭司处收集 4 张阿塔莱卷轴。","找工作吗？我需要一个勇敢的灵魂向南前往沼泽。\n\n在沉没神庙中，你会找到高阶祭司和巫医。这些巨魔携带着卷轴，上面写着血神哈卡本人的疯狂预言。我会密切关注他的追随者，这些卷轴会帮助我做到这一点。说什么？","pfQuest-epoch zhCN","Invocation of The Blood God"},
    [26319]={"知识遗产","前往托尔巴拉德岛上的巴拉丁要塞，寻找卡莱德拉·黎明微风有兴趣恢复的书籍。","旅行者，请原谅我的打扰，但您的名字已经在贵族院中流传，我一直在等待一位著名的英雄来参观城堡。\n\n随着奎尔萨拉斯和达拉然的陷落，我的人民的大部分知识都消失了。然而，肯瑞托在托尔巴拉德岛上的巴拉丁要塞监狱据点设有一座图书馆。监狱里可能保存着许多我非常想保存的书籍。\n\n我可以说服你协助我完成这项工作吗？你会得到很好的回报。","pfQuest-epoch zhCN","A Legacy of Knowledge"},
    [26320]={"知识遗产","前往托尔巴拉德岛上的巴拉丁要塞，寻找游学者阿什曼有兴趣恢复的书籍。","旅行者，请原谅我的打扰，但您的名字已经在长老们中流传，我一直在等待一位著名的英雄来访问精神崛起。\n\n随着奎尔萨拉斯和达拉然的陷落，高等精灵的大部分知识都丢失了。然而，肯瑞托在托尔巴拉德岛上的巴拉丁要塞监狱据点设有一座图书馆。监狱里可能保存着许多我非常想保存的书籍。\n\n我可以说服你协助我完成这项工作吗？你会得到很好的回报。","pfQuest-epoch zhCN","A Legacy of Knowledge"},
    [26321]={"未完成的任务","从托尔巴拉德岛上找回丽贝卡·马丁丢失的传家宝。","你——是的你！冒险家！也许你会听我的！\n\n几周来我一直在向暴风要塞的各种有权势的人请愿，但他们不会对我的请求给予任何关注。第二次世界大战前，我的家人曾住在托尔巴拉德岛上。他们中的大多数人都死在那里，但我的一个叔叔逃脱了。在他去世之前，他告诉我一件珍贵的传家宝被藏在岛上一个安全的地方。但现在有传言说托尔巴拉德出现了海盗！他们在追寻宝藏，我就知道。\n\n看，$C，我迫切需要有人去岛上取回宝藏。拿着这把钥匙！它将打开隐藏宝藏的隔间。请把我家族的遗产还给我吧！","pfQuest-epoch zhCN","An Unfinished Task"},
    [26322]={"未完成的任务","将丢失的传家宝归还给暴风城的丽贝卡·马丁。","给你的钥匙似乎无法打开隐藏隔间内的小密码箱。你所能做的就是把密码箱带回给丽贝卡·马丁，并希望里面有她正在寻找的宝藏。","pfQuest-epoch zhCN","An Unfinished Task"},
    [26323]={"未完成的任务","从托尔巴拉德岛上找回乔治亚娜·马丁丢失的传家宝。","你——是的你！冒险家！也许你会听我的！\n\n几周来我一直在向幽暗城的各种有权势的人请愿，但他们不会对我的请求给予任何关注。第二次世界大战前，我的家人曾住在托尔巴拉德岛上。他们中的大多数人都死在那里，但我的一个叔叔逃脱了。在他去世之前，他告诉我一件珍贵的传家宝被藏在岛上一个安全的地方。但现在有传言说托尔巴拉德出现了海盗！他们在追寻宝藏，我就知道。\n\n看，$C，我迫切需要有人去岛上取回宝藏。拿着这把钥匙！它将打开隐藏宝藏的隔间。请把我家族的遗产还给我吧！","pfQuest-epoch zhCN","An Unfinished Task"},
    [26324]={"未完成的任务","将丢失的传家宝归还给幽暗城的乔治亚娜·马丁。","给你的钥匙似乎无法打开隐藏隔间内的小密码箱。您所能做的就是将密码箱带回给乔治亚娜·马丁，并希望里面有她正在寻找的宝藏。","pfQuest-epoch zhCN","An Unfinished Task"},
    [26325]={"埋藏的宝藏","找到合适的工具来挖掘您发现的土堆。","这不起眼的土堆里似乎并没有藏着什么宝藏。当你在松散的泥土中翻滚时，你的手指似乎在感觉消失之前抓住了箱子的边缘。\n\n也许您需要专门的设备来挖掘箱子？","pfQuest-epoch zhCN","Buried Treasure"},
    [26326]={"进入炼狱","与可以告诉你更多关于不祥白色球体的人交谈。","布莱克斯通船长箱子里的宝藏中有一个奇怪的乳白色球体，它闪烁着不祥的红光。当你触摸它光滑的表面时，这个球体会让人感到一种奇怪的安心感。了解有关此物品的更多信息可能是明智之举。","pfQuest-epoch zhCN","Into Purgatory"},
    [26327]={"进入炼狱","找到黑石船长的前船员，了解他们对帕雷斯之眼的起源有何看法。","$C，你现在被一只帕雷斯之眼束缚住了，它所受的魔法比这座岛上的居民陷入炼狱的魔法还要强大——而我们也因为虐待南海镇拘留营中的人而受到圣光的束缚。\n\n黑石船长选择这个岛来隐藏他的宝藏绝非偶然。在被招入南海镇的私掠船队之前，他经历了多年的痛苦。作为我们赎罪的一部分，我们守护他的宝藏是一项恰当的任务。这个故事本来应该与你无关，但你现在却深陷其中。如果你不想让他的错误占据你的生活，你就必须解开诅咒，就像黑石未能做到的那样。\n\n我不知道黑石之眼如何被黑石拥有的细节，但我相信你必须追溯到它的来源，才能打破将它与你联系在一起的诅咒。黑石带着他的三名船员来到这个岛上。如果您不想像黑石那样陷入疯狂，就去找他们吧。","pfQuest-epoch zhCN","Into Purgatory"},
    [26328]={"进入炼狱","使用您收集的信息来寻找 Blackstone 的宝藏。","那么三位船员说宝藏在菲拉斯的一个纳迦居住的洞穴里？\n\n我对卡利姆多一无所知，无法为您提供进一步的建议，但如果您搜索那片土地的海边洞穴，我相信您会找到您想要的东西。\n\n再拿一把您用来挖箱子的铲子。我确信您会需要它。\n\n再见，$C。我祈祷我们没有理由再见面。","pfQuest-epoch zhCN","Into Purgatory"},
    [26329]={"另一种生活的梦想","找到黑石和他的情人共同的朋友。也许黑石的日志能提供他在哪里有朋友的线索？","你发现的不是宝藏和“面纱束缚者”诅咒的起源，而是一张说明黑石将宝藏藏在别处以保护他的船员的注释。这一崇高的姿态谴责你继续携带被诅咒的帕雷斯之眼。\n\n只有黑石的爱才知道宝藏的真正位置。找到她是你摆脱诅咒的唯一希望。","pfQuest-epoch zhCN","Dreams of Another Life"},
    [26330]={"另一种生活的梦想","保护帕拉·恐怖图腾，让她带领您前往宝藏。","这个农场是我们的梦想。我想我一直都知道他永远不会真正回到这里。作为一名私掠者是一项危险的工作，然后当他转向彻底的海盗行为时......\n\n我不知道黑石是如何设法将宝藏运到这里的，但他把它藏在附近的一个洞穴里。我想这是他给我的最后一份礼物，但我没能拿到它。它被来自面纱之外的灵魂所困扰。他们会试图反击我们。但如果你足够强大，能够在战斗中击败我的爱人，并从把你带到这里的诅咒中幸存下来，也许你就能强大到足以击败他们。\n\n当你准备好离开时，请告诉我。","pfQuest-epoch zhCN","Dreams of Another Life"},
    [26331]={"掠夺海盗","乘坐栖息之主霍金斯的狮鹫，调查海盗袭击托尔巴拉德的事件。","三个月前，我们的瞭望员发现地平线上有帆和船只。他声称他以前见过他们的横幅，但他似乎太害怕而无法讲述在哪里或与谁一起看到的。他们被发现后不久，炮火声就在水面上回响。\n\n那个方向只有一个岛屿：托尔巴拉德，旧肯瑞托监狱的所在地。有人在那里想要什么？这是一次突袭吗？逃跑？\n\n我很好奇，我迷信的船员们很害怕。你可以帮忙！与栖息大师霍金斯交谈并要求搭车前往托尔巴拉德。我需要一名侦察员来观察这座岛屿并让我知道发生了什么事。","pfQuest-epoch zhCN","Plundering Pirates"},
    [26332]={"掠夺海盗","在阿拉希高地的法迪尔湾找到斯蒂尔古特船长。","听着！我收到了来自……好吧，就说一个盟友的消息，声称托尔巴拉德似乎正在发生海军袭击。\n\n那个岛不值钱，所以收到这份报告有点可疑。\n\n前往法迪尔湾，与斯蒂尔古特船长交谈，告诉他是我派你来的。他们会知道它是关于什么的。","pfQuest-epoch zhCN","Plundering Pirates"},
    [26333]={"我的船王国","获取 Winkey 建造一艘船所需的物资，并将它们带到她位于塔纳利斯的岛屿。","我不会游泳，我现在当然不会浪费时间学习！我需要的是建造我自己的船的组件 - 只是一件小事，所以我在这里要求不多。\n\n这是组件列表；现在带着你的防水盔甲跑吧，把这些东西带给我。你越早走，越早回来，越早摆脱诅咒，我就能睡在一张合适的床上。\n\n哦——你从哪里得到那些东西？嗯，我听说西瘟疫之地有一家伐木场，也许你可以在那里买到一些。符文布就放在任何人都可以获得的地方，对吧？线由贸易商出售，而沥青壶则来自其他海盗。","pfQuest-epoch zhCN","My Kingdom for a Ship"},
    [26334]={"我的船王国","获取 Winkey 为自己建造一艘船所需的工具。","我光靠双手是造不成船的！我需要合适的工具来组装这些组件，并且我需要你帮我获取它们。因为自从你上次来到这里以来，我花了这段时间做关于奶酪的白日梦和晒黑皮肤，而不是学习游泳。有梦想很重要！它让你继续前进。你见过多少棕褐色侏儒？我的金色皮肤会引起轰动。\n\n不管怎样，我需要一把铁匠锤、一把弧光扳手、50把铜螺栓和一把侏儒大小的竖锯。熟练的工程师可以帮助解决其中一些问题，但拼图只来自一个地方 - 诺莫瑞根！","pfQuest-epoch zhCN","My Kingdom for a Ship"},
    [26335]={"斯蒂尔的复仇","确定洛林·雷姆卡是生还是死。","正如我告诉过你的，我的父亲为了让黑石和他的其他兽人船员免遭监禁而献出了自己的生命。在我父亲麾下航行的兽人是从拘留营中征召入伍的，并在南海镇私掠船队被击沉后被送回这些营地。我父亲请求释放他们，但遭到塞尔格拉姆法官和督军洛林·雷姆卡的拒绝。 \n\n塞尔格拉姆已经死了一段时间了，但我相信雷姆卡还活着。如果她听从道理，我父亲就不会觉得有必要把兽人赶出营地，他也不会因为这个麻烦而死。我的良心不会让我休息，除非她为他的死付出代价，但我不知道她现在在哪里。 \n\n雷姆卡养了一个女兽人作为私人奴隶。她的名字叫希腊语。雷姆卡在营地还有一位名叫瓦里克的随员。我也不知道那些人是否还活着，但如果你能找到其中任何一个，也许就能找到雷姆卡的下落。","pfQuest-epoch zhCN","Stewel's Revenge"},
    [26336]={"斯蒂尔的复仇","杀死洛林·雷姆卡。","我希望我能依靠司法系统来给予适当的惩罚，但暴风城的领导人不太可能关心多年前在洛丹伦犯下的罪行。  \n\n我父亲不会同意我为他报仇的愿望。他甚至让我保证，如果手术出了问题，不会对那些傻瓜出手。有一种方法可以让我信守诺言，这样我的良心就会清白。你必须充当我的复仇之手。如果你这样做，我会告诉你你想知道的事情。\n\n洛林雷姆卡必须死。血债血偿。","pfQuest-epoch zhCN","Stewel's Revenge"},
    [26337]={"死灵法师和后裔","进入托尔巴拉德岛上的巴拉丁要塞并杀死空心阿斯蒂洛斯和纳兹拉什。","冰雹$C。如果您是来寻找秘密工作的，我可以向您保证，您来对地方了。\n\n我听说巴拉丁监狱岛上的监狱发生了一次小规模越狱。有几个囚犯被关押在那里，我真的不希望他们逃脱。两人都是强大的魔法使用者，可以破坏幽暗城。我们尤其不希望更多的死灵法师到处乱跑。\n\n如果你不介意去阿拉希高地的法迪尔湾短途旅行，然后搭乘航班飞往托尔巴拉德，我会让你花点时间确保阿斯蒂洛斯和纳兹拉什永远不会离开岛屿。","pfQuest-epoch zhCN","The Necromancer and the Scion"},
    [26338]={"巴拉丁要塞可能陷落","在 SI:7 中寻找可以向您提供有关巴拉丁要塞当前状态的更多信息的人。","作为暴风城海军元帅，我收到有关公海上发生的各种事件和欺诈行为的报告。最近，托尔巴拉德岛据点传来了令人不安的报告。海盗可能已经占领了古老的肯瑞托监狱。\n\n目前这个谣言尚未得到证实。我需要有人前往托尔巴拉德评估这个问题。你看起来很有能力——你的联盟需要你，冒险家。\n\n出发前在 SI:7 停留。他们可能有更多信息。","pfQuest-epoch zhCN","The Possible Fall of Baradin Hold"},
    [26339]={"巴拉丁要塞可能陷落","调查托尔巴拉德岛上巴拉丁要塞的情况，看看海盗袭击的传言是否属实。","托尔巴拉德岛是巴拉丁监狱的所在地，但巴拉丁并不是一座普通的监狱。世界上一些最恶劣的生物被囚禁在那里。甚至还有一个科赞无法控制的！\n\n所以，是的，我们必须知道海盗是否已经占领了监狱 - 但如果他们占领了，我们也必须采取一些措施。当你到达那里后，我会让你自己找出最好的行动方案。\n\n说到这里，如果你不知道如何到达那里，你就必须前往阿拉希高地的法迪尔湾。那里的飞行管理员会很乐意为您安排。","pfQuest-epoch zhCN","The Possible Fall of Baradin Hold"},
    [26340]={"巴拉丁要塞可能陷落","杀死袭击巴拉丁要塞的海盗：格拉古特、卡里普索和海盗领主黑石。","伦齐克指示您，如果您发现谣言属实，请自行解决问题。\n\n解决这种情况的最简单方法就是消灭目前控制巴拉丁要塞的海盗。\n\n您需要在监狱中杀出一条血路，以确保恢复秩序。","pfQuest-epoch zhCN","The Possible Fall of Baradin Hold"},
    [26341]={"巴拉丁要塞可能陷落","调查托尔巴拉德岛上巴拉丁要塞的情况，看看海盗袭击的传言是否属实。","部落英雄，你们的酋长需要您的帮助！\n\n托尔巴拉德岛是巴拉丁监狱的所在地——那里关押着世界上一些最可怕的野兽。连科赞都抓不住的！\n\n有传言说海盗已经占领了监狱。我们需要调查。一旦你到达那里，我会让你找出最佳行动方案。\n\n说到这里，如果你不知道如何到达那里，你就必须前往阿拉希高地的法迪尔湾。那里的飞行管理员会很乐意为您安排。","pfQuest-epoch zhCN","The Possible Fall of Baradin Hold"},
    [26342]={"巴拉丁要塞可能陷落","杀死袭击巴拉丁要塞的海盗：格鲁克、卡里普索和海盗领主黑石。","沃金指示您，如果您发现谣言属实，请自行解决问题。\n\n解决问题的最简单方法就是消灭目前控制巴拉丁要塞的海盗。\n\n您需要杀出一条血路穿过监狱，以确保恢复秩序。","pfQuest-epoch zhCN","The Possible Fall of Baradin Hold"},
    [26343]={"致所有我曾经爱过的恶魔","进入托尔巴拉德岛上的巴拉丁要塞并杀死莫鲁姆斯和达克马尔。","冰雹$C。如果您是来寻找秘密工作的，我可以向您保证，您来对地方了。\n\n我听说巴拉丁监狱岛上的监狱发生了一次小规模越狱。有几个囚犯被关押在那里，我真的不希望他们逃脱。他们很有可能会来找我，而我不希望暴风城出现那种混乱。\n\n如果你不介意去阿拉希高地的法迪尔湾短途旅行，然后转机飞往托尔巴拉德，我会让你花点时间确保莫鲁姆斯和达克马尔永远不会离开这个岛。","pfQuest-epoch zhCN","To All the Demons I Used to Love"},
    [26344]={"你挠我的背...","找到荆棘谷的老大奥格尔索普并消灭她。","我怀疑你正在寻找这颗球体的其余宝藏，我有个好消息——它被大量埋在我们捕获船只的地方附近。坏消息是，我只有部分位置。黑石将坐标分配给我、温克斯和朱尼尔。因此，您必须与他们交谈才能获得其余信息。\n\n但首先 - 我与竞争对手卡特尔成员之间存在一些问题。自从离开黑石团队后，我一直在黑水袭击者队担任自由职业者，并且我不止一次与风险投资公司的老板奥格尔索普锁定了扳机。我厌倦了每次走出藏宝海湾时都必须小心翼翼。帮我带她出去，我会告诉你你想知道的事情。 \n\n她在荆棘谷的某个地方有一个小基地，但我不知道它在哪里。","pfQuest-epoch zhCN","You Scratch My Back..."},
    [26345]={"好消息","在棘齿城与卡莱塔卡·温特布拉夫会面，讨论诺甘农圆盘。","我有个好消息，$N！探险者联盟能够破译诺甘农圆盘上的一些符文。奇怪的是，它们与古代陶拉赫语中使用的符文很相似。\n\n我们找到了一位愿意与我们合作破译符文的牛头人联系人，我们希望你能与她合作。她同意从雷霆崖前往棘齿城与你会面。在那里的旅店与卡莱塔卡·温特布拉夫会面，我们离奥丹姆的开业又近了一步！","pfQuest-epoch zhCN","The Good News"},
    [26346]={"激动人心的发现","在棘齿城与卡莱塔卡·温特布拉夫会面，讨论诺甘农圆盘。","不久前，探险者联盟收到了一件名为诺甘农圆盘的神器。我们一直在尝试从光盘中收集一些信息，为了继续进行，我们需要一位精通陶拉赫语的专家。\n\n我们找到了一位愿意与我们合作的牛头人联系人，我们需要一名信使与她会面。我听说你在镇上推荐过，所以我想让你去棘齿城的断龙骨酒馆见见卡莱塔卡·温特布拉夫。如果我们是对的，这些圆盘可能会打开奥丹姆的古老设施！","pfQuest-epoch zhCN","An Exciting Discovery"},
    [26347]={"好消息","在棘齿城和费伍德森林之间的路上找到卡莱塔卡·温特布拉夫。","老实说，面对面与 $R 见面有点令人伤脑筋，但我母亲不会让派系恩怨妨碍对知识的追求。\n\n 不过，她对来这里的旅行很担心，因为她认为有人在跟踪我们。她决定不再在这里等待，并希望我告诉你她要去费伍德森林。既然她是步行的，我相信你能追上她。\n\n我很担心她，$R，但我相信我妈妈能照顾好自己。","pfQuest-epoch zhCN","The Good News"},
    [26348]={"坏消息","带着坏消息返回棘齿城的穆林·温特布拉夫。","卡莱塔卡·温特布拉夫的尸体上所有值钱的东西都被洗劫一空。她的手上没有任何防御痕迹，看来是遭到伏击了。就在喉咙上的一刀，说明了凶手的效率。\n\n你正要离开，这时你在附近的泥里发现了一个奇怪的蹄印。你记住了那个蹄印的细节，知道你必须回到棘齿城的穆林·温特布拉夫并告诉他，他母亲对她被跟踪的怀疑似乎是正确的——这对每个人都不利。","pfQuest-epoch zhCN","The Bad News"},
    [26349]={"坏消息","将卡莱塔卡的加密笔记交给铁炉堡的高级探险家麦格拉斯。","<当穆林努力让自己平静下来时，你描述了你在泥里看到的蹄印。>\n\n我希望能帮助你，但我现在无法集中注意力。但在你离开之前，我妈妈给了我一些东西，你应该拥有，$R.\n\n我妈妈告诉我，如果她真的出了什么事，她会给你这张纸条。我希望这对您需要她的任何事情有所帮助。\n\n如果我说我再也不想见到另一个$R，请原谅我。","pfQuest-epoch zhCN","The Bad News"},
    [26350]={"好消息又来","与铁炉堡探险家大厅的历史学家卡尼克交谈。","我将致力于破译卡莱塔卡的信息，但在你离开期间，探险者联盟的其他一些成员在破译奥丹姆板块的位置方面取得了突破。\n\n如果您想了解更多信息，请与历史学家卡尼克交谈。","pfQuest-epoch zhCN","The Good News Again"},
    [26351]={"好消息又来","搜索冬泉谷的暗语峡谷，寻找奥丹姆板块位置的线索。","探险家联盟破译了几条信息，表明奥丹姆板片被保存在持续冒烟的地方。另外，“峡谷”和“洞穴”这两个词似乎经常出现。\n\n似乎很明显提到了灼热峡谷，但请记住，这些圆盘是在拉格纳罗斯被召唤之前很久就创建的。那时灼热峡谷还不存在。\n\n但冬泉谷的暗语峡谷却存在。\n\n我们希望你发挥你的才华，在暗语峡谷中搜寻奥丹姆石板的任何迹象。报告您发现的任何情况。","pfQuest-epoch zhCN","The Good News Again"},
    [26352]={"坏消息又来","带着唤地者的消息返回铁炉堡的历史学家卡尼克。","我知道你在寻求什么，我也看到了你寻求它的勇气。请放心，我不会轻易说这句话，因为我已经看到有多少凡人会为了追求知识而牺牲。\n\n请注意，您还没有准备好获得奥丹姆板片。你还没有准备好迎接门后的一切。就连泰坦也没有准备好接受他们的发现，这就是为什么板块和圆盘被分开并散落在风中的原因。\n\n如果你继续沿着这条踪迹走下去，它将释放出难以形容的厄运。现在就走吧，$R。这个探索已经结束了。我强烈建议你找一个新的。","pfQuest-epoch zhCN","The Bad News Again"},
    [26353]={"好消息","在藏宝海湾与海德里格·铁石会面，讨论诺甘农圆盘。","我有个好消息，$N！博学者能够破译诺甘农圆盘上的一些符文。它们是用古老的矮人语言写成的。\n\n我们找到了一位愿意与我们合作破译符文的矮人联系人，我们希望您能与他见面。他同意从铁炉堡前往棘齿城与你会面。到那里的旅店与海德里格·铁石会面，我们离奥丹姆的开业又近了一步！","pfQuest-epoch zhCN","The Good News"},
    [26354]={"激动人心的发现","在棘齿城与海德里格·铁石会面，讨论诺甘农圆盘。","不久前，Lorespeakers 获得了一件名为诺甘农圆盘的神器。我们一直在尝试从光盘中收集一些信息并继续进行，我们需要一位矮人语言专家。\n\n我们找到了一位愿意与我们合作的矮人联系人，我们需要一名信使与他会面。我听说你在镇上推荐过，所以我想让你去棘齿城的断龙骨酒馆见见海德里格·铁石。如果我们是对的，这些圆盘可能会打开奥丹姆的古老设施！","pfQuest-epoch zhCN","An Exciting Discovery"},
    [26355]={"好消息","在棘齿城和费伍德森林之间的路上找到海德里格·铁石。","老实说，与“PH0”面对面的会面有点让人伤脑筋，但爸爸不会让派系恩怨妨碍对知识的追求。\n\n不过他对来这里的旅行很担心。他以为有人在监视我们，所以他就自己出发了。他要我告诉你他要去费伍德森林。既然他是步行的，我相信你能追上他。\n\n我很担心他，$R，但我相信我爸爸能照顾好自己。","pfQuest-epoch zhCN","The Good News"},
    [26356]={"坏消息","带着坏消息返回棘齿城的耐莉·艾恩斯通。","海德里格·铁石的尸体上所有值钱的东西都被洗劫一空。他的手上没有任何防御痕迹，看来是遭到伏击了。就在喉咙上的一刀，说明了凶手的效率。\n\n你正要离开，这时你发现附近的泥里有一个脚印。你记住了那个脚印的细节，知道你必须回到棘齿城的耐莉·艾恩斯通并告诉她，她父亲对他被跟踪的怀疑似乎是正确的——这对每个人都不利。","pfQuest-epoch zhCN","The Bad News"},
    [26357]={"坏消息","将海德里格的加密信息交给雷霆崖的贤者真理探索者。","<当耐莉努力让自己平静下来时，你描述了你在泥里看到的脚印。>\n\n我希望能帮助你，但那个奇怪的鞋履我听起来不熟悉。但有件事，$R.\n\n我爸爸告诉我，如果发生什么事，我会给你这张纸条。我希望它对您需要我爸爸的任何事情有所帮助。\n\n请原谅我，如果我说我再也不想看到另一个$R。","pfQuest-epoch zhCN","The Bad News"},
    [26358]={"好消息又来","与雷霆崖的灵魂高地的贤者娜莎交谈。","我会努力破译海德里格的信息，但在你离开期间，其他一些博学者相信他们在破译奥丹姆石板的位置方面取得了突破。\n\n如果您想了解更多信息，请与灵界的贤者纳莎交谈。","pfQuest-epoch zhCN","The Good News Again"},
    [26359]={"好消息又来","搜索冬泉谷的暗语峡谷，寻找奥丹姆板块位置的线索。","博学者破译了几条信息，表明奥丹姆板片被保存在有持续烟雾的地方。另外，“峡谷”和“洞穴”这两个词似乎经常出现。\n\n似乎很明显提到了灼热峡谷，但请记住，这些圆盘是在拉格纳罗斯被召唤之前很久就创建的。那时灼热峡谷还不存在。\n\n但冬泉谷的暗语峡谷却存在。\n\n我们希望你发挥你的才华，在暗语峡谷中搜寻奥丹姆石板的任何迹象。报告您发现的任何情况。","pfQuest-epoch zhCN","The Good News Again"},
    [26360]={"坏消息又来","带着唤地者的信息返回雷霆崖的贤者娜莎那里。","我知道你在寻求什么，我也看到了你寻求它的勇气。请放心，我不会轻易说这句话，因为我已经看到了凡人会为追求知识而牺牲多少。\n\n请注意：您还没有准备好获得奥丹姆的板片。你还没有准备好迎接门后的一切。就连泰坦也没有准备好接受他们的发现，这就是为什么板块和圆盘被分开并散落在风中的原因。\n\n如果你继续沿着这条踪迹走下去，它将释放出难以形容的厄运。现在就走吧，$R。这个探索已经结束了。我强烈建议你找一个新的。","pfQuest-epoch zhCN","The Bad News Again"},
    [26361]={"召唤小冲突：石爪山脉","在石爪山脉内找到并杀死 5 名部落成员。","石爪山脉属于联盟，我们必须不断地证明这一点。追捕部落成员并代表军队杀死他们，以证明你的价值并晋升。","pfQuest-epoch zhCN","Call to Skirmish: Stonetalon Mountains"},
